"""Build the public data.json for the dark site from the hub export.

Public rules:
- no project, client, brand-of-client or character names anywhere;
- templates without examples from her projects;
- course summaries (Higgsfield Academy) stay, with sources;
- moderation section keeps only false-positive avoidance and limits.
"""
import json, glob, os, re, sys

EXP = sys.argv[1]
OUT = sys.argv[2]
ACADEMY = "https://higgsfield.ai/academy"


def load(coll):
    res = {}
    for f in sorted(glob.glob(os.path.join(EXP, coll, "*.json"))):
        d = json.load(open(f, encoding="utf-8"))
        x = d.get("data", d)
        res[os.path.basename(f)[:-5]] = x
    return res


T, G, M, R = load("templates"), load("models"), load("moves"), load("rules")

