rules = []
for k, x in R.items():
    if k in EXCLUDE:
        continue
    cat = R_CAT.get(k) or CAT_RENAME.get(x.get("category"), x.get("category"))
    t, w = r_over.get(k, (None, None))
    rules.append({"id": k, "cat": cat, "text": t or x.get("text", ""), "why": w or x.get("why", ""), "_o": x.get("order", 0)})
rules.sort(key=lambda r: (RCATS.index(r["cat"]) if r["cat"] in RCATS else 99, r["_o"]))
for i, r in enumerate(rules, 1):
    r["code"] = "R%02d" % i
    del r["_o"]

