from PIL import Image


def I(name, cap):
    d = {"src": "img/" + name + ".webp", "cap": cap}
    w, h = Image.open(os.path.join(os.path.dirname(os.path.abspath(OUT)), "img", name + ".webp")).size
    if h > w:
        d["tall"] = True
    return d

